import json, numpy as np
d=json.load(open('validaciones/1.json'))
for k in range(6):
    P=d[k]['pasos']
    U=np.array([p['acciones'] for p in P]); Y=np.array([p['lecturas'] for p in P])
    best=[]
    for lag0 in range(4):
      for lag1 in range(4):
        rows=[];ys=[]
        for t in range(30,len(P)):
            if abs(Y[t,1])<1.1:
                rows.append([1,U[t-lag0,0],U[t-lag1,1]]); ys.append(Y[t,1])
        if len(rows)<5: continue
        A=np.array(rows); c,res,_,_=np.linalg.lstsq(A,np.array(ys),rcond=None)
        r=np.sqrt(np.mean((A@c-ys)**2)); best.append((round(r,3),lag0,lag1,np.round(c,3),len(rows)))
    best.sort(key=lambda x:x[0]); print(k,best[:2])
